import java.util.*;

class Solution {
  public List<Integer> numIslands2(int m, int n, int[][] positions) {
    int[] parent = new int[m * n];
    Arrays.fill(parent, -1);
    List<Integer> result = new ArrayList<>();
    int islands = 0;
    int[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    for (int[] position : positions) {
      int row = position[0];
      int column = position[1];
      int index = row * n + column;
      if (parent[index] != -1) {
        result.add(islands);
        continue;
      }
      parent[index] = index;
      islands++;
      for (int[] direction : directions) {
        int nextRow = row + direction[0];
        int nextColumn = column + direction[1];
        if (nextRow < 0 || nextRow >= m || nextColumn < 0 || nextColumn >= n) continue;
        int neighbor = nextRow * n + nextColumn;
        if (parent[neighbor] != -1 && union(parent, index, neighbor)) islands--;
      }
      result.add(islands);
    }
    return result;
  }

  private int find(int[] parent, int node) {
    while (parent[node] != node) {
      parent[node] = parent[parent[node]];
      node = parent[node];
    }
    return node;
  }

  private boolean union(int[] parent, int first, int second) {
    first = find(parent, first);
    second = find(parent, second);
    if (first == second) return false;
    parent[first] = second;
    return true;
  }
}
